function validate([s, t, maxCost]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (t.length !== s.length) return 's and t must have the same length.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase letters.';
  if (!Number.isInteger(maxCost) || maxCost < 0 || maxCost > 1000000) return 'maxCost is an integer from 0 to 1000000.';
  return null;
}

