function equalSubstring(s, t, maxCost) {
  let answer = 0;
  for (let start = 0; start < s.length; start++) {
    for (let end = start; end < s.length; end++) {
      let total = 0;
      for (let k = start; k <= end; k++) total += Math.abs(s.charCodeAt(k) - t.charCodeAt(k));
      if (total <= maxCost && end - start + 1 > answer) answer = end - start + 1;
    }
  }
