function generate(rand, size) {
  const n = size === 'large' ? 5000 : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? 26 : (rand() < 0.5 ? 4 : 26);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * span));
  let s = '';
  let t = '';
  for (let i = 0; i < n; i++) {
    const a = letter();
    s += a;
    t += rand() < 0.2 ? a : letter();
  }
  const maxCost = size === 'large' ? Math.floor(rand() * 40000) : Math.floor(rand() * 30);
  return [s, t, maxCost];
}
